// Morphology of Flowering Plant - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'

export const MORPHOLOGY_FLOWERING_PLANTS = [

  // ============ ROOT ============
  { id: 'mofp-1', type: 'mcq', question: 'The radicle of a germinating seed elongates and forms the:', options: ['Tap root', 'Adventitious root', 'Fibrous root', 'Prop root'], correctIndex: 0, explanation: 'The radicle grows downward and gives rise to the primary or tap root, which bears lateral roots of several orders.', difficulty: 'easy' },
  { id: 'mofp-2', type: 'mcq', question: 'Roots that arise from parts of the plant other than the radicle are called:', options: ['Tap roots', 'Adventitious roots', 'Primary roots', 'Secondary roots'], correctIndex: 1, explanation: 'Adventitious roots develop from any part of the plant body other than the radicle, e.g., roots in grass or Monocotyledons.', difficulty: 'easy' },
  { id: 'mofp-3', type: 'mcq', question: 'The root cap in aquatic plants like Pistia and Eichhornia is protected by a structure called:', options: ['Velamen', 'Pneumathode', 'Root pocket', 'Piliferous layer'], correctIndex: 2, explanation: 'In many aquatic plants, the root cap is not well organised and a root pocket protects the root tip instead.', difficulty: 'hard' },
  { id: 'mofp-4', type: 'mcq', question: 'Conical, fusiform and napiform are types of root modifications seen in:', options: ['Adventitious roots for storage', 'Tap roots for storage', 'Prop roots', 'Parasitic roots'], correctIndex: 1, explanation: 'Tap roots get modified into conical (carrot), fusiform (radish) and napiform (turnip) shapes for storing food.', difficulty: 'medium' },
  { id: 'mofp-5', type: 'mcq', question: 'Root tubers, seen in sweet potato, are modifications of:', options: ['Adventitious roots', 'Tap roots', 'Prop roots', 'Stilt roots'], correctIndex: 0, explanation: 'In sweet potato, adventitious roots swell irregularly to store food, forming root tubers.', difficulty: 'easy' },
  { id: 'mofp-6', type: 'mcq', question: 'Prop roots that grow from the branches of a tree and hang down to the soil are best exemplified by:', options: ['Maize', 'Screw pine', 'Banyan tree', 'Sugarcane'], correctIndex: 2, explanation: 'In the banyan tree, thick pillar-like prop roots arise from horizontal branches and reach the soil for mechanical support.', difficulty: 'easy' },
  { id: 'mofp-7', type: 'mcq', question: 'Stilt roots, which arise from the lower nodes of the stem and provide extra support, are found in:', options: ['Ficus bengalensis', 'Maize and sugarcane', 'Rhizophora', 'Orchids'], correctIndex: 1, explanation: 'In maize and sugarcane, adventitious roots arise from the lower nodes and grow obliquely into the soil as stilt roots.', difficulty: 'medium' },
  { id: 'mofp-8', type: 'mcq', question: 'Pneumatophores are respiratory roots found in plants growing in:', options: ['Dry rocky soils', 'Saline swampy areas', 'Cold alpine regions', 'Nutrient-rich loamy soils'], correctIndex: 1, explanation: 'In saline swamps (mangroves), many roots grow vertically upward and have pores called pneumatophores for gas exchange.', difficulty: 'medium' },
  { id: 'mofp-9', type: 'mcq', question: 'Velamen tissue, which helps absorb moisture from the atmosphere, is associated with which type of root?', options: ['Epiphytic roots of orchids', 'Parasitic roots of Cuscuta', 'Floating roots of Jussiaea', 'Assimilatory roots of Tinospora'], correctIndex: 0, explanation: 'Epiphytic roots hanging in the air possess a spongy tissue called velamen that absorbs moisture from the atmosphere.', difficulty: 'medium' },
  { id: 'mofp-10', type: 'mcq', question: 'The parasitic roots by which Cuscuta obtains nourishment from its host are called:', options: ['Haustoria', 'Pneumatophores', 'Nodules', 'Velamen roots'], correctIndex: 0, explanation: 'Cuscuta develops sucker-like haustorial roots that penetrate the host tissue to absorb nutrients.', difficulty: 'easy' },
  { id: 'mofp-11', type: 'mcq', question: 'Root nodules in leguminous plants house symbiotic bacteria of the genus:', options: ['Nostoc', 'Rhizobium', 'Azotobacter', 'Anabaena'], correctIndex: 1, explanation: 'Leguminous roots develop nodules containing symbiotic nitrogen-fixing bacteria, Rhizobium.', difficulty: 'easy' },
  { id: 'mofp-12', type: 'assertion', question: 'Assertion (A): Fibrous root systems are common in most monocotyledonous plants.\nReason (R): In monocots, the radicle is short-lived and is replaced by a cluster of roots arising from the base of the stem.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'In monocots the radicle is short-lived and is replaced by adventitious roots forming a fibrous root system, which correctly explains the assertion.', difficulty: 'medium' },
  { id: 'mofp-13', type: 'matching', question: 'Match Column I (root modification) with Column II (example):\nColumn I: A. Prop roots  B. Stilt roots  C. Pneumatophores  D. Tuberous roots\nColumn II: i. Beet  ii. Banyan  iii. Rhizophora  iv. Maize', options: ['A-ii, B-iv, C-iii, D-i', 'A-iv, B-ii, C-i, D-iii', 'A-ii, B-iii, C-iv, D-i', 'A-i, B-ii, C-iii, D-iv'], correctIndex: 0, explanation: 'Prop roots occur in banyan, stilt roots in maize, pneumatophores in mangroves like Rhizophora, and tuberous storage roots in beet.', difficulty: 'medium' },
  { id: 'mofp-14', type: 'count', question: 'Consider the following statements about roots:\n1. The tap root system develops from the radicle.\n2. Adventitious roots always store food.\n3. Root hairs are unicellular extensions of epidermal cells.\n4. Root cap protects the growing apex in all plants including aquatic ones.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (adventitious roots are not always storage roots), and statement 4 is wrong (aquatic plants like Pistia have root pockets instead of a true root cap).', difficulty: 'hard' },
  { id: 'mofp-15', type: 'mcq', question: 'The primary function of root hairs is to:', options: ['Anchor the plant firmly', 'Increase the surface area for absorption of water and minerals', 'Store food materials', 'Perform photosynthesis'], correctIndex: 1, explanation: 'Root hairs are delicate, thread-like unicellular structures that greatly increase the absorptive surface area of roots.', difficulty: 'easy' },

  // ============ STEM ============
  { id: 'mofp-16', type: 'mcq', question: 'The stem develops from which part of the embryo?', options: ['Radicle', 'Plumule', 'Cotyledon', 'Hypocotyl'], correctIndex: 1, explanation: 'The plumule of the embryo develops into the shoot system, which bears the stem, leaves and flowers.', difficulty: 'easy' },
  { id: 'mofp-17', type: 'mcq', question: 'Nodes and internodes are characteristic external features of the:', options: ['Root', 'Stem', 'Leaf', 'Flower'], correctIndex: 1, explanation: 'The region of the stem where leaves are borne is called a node, and the portion between two nodes is called an internode.', difficulty: 'easy' },
  { id: 'mofp-18', type: 'mcq', question: 'The underground stem modification of ginger, in which the stem grows horizontally and stores food, is called:', options: ['Tuber', 'Rhizome', 'Corm', 'Bulb'], correctIndex: 1, explanation: 'Ginger has a rhizome — a horizontally growing underground stem with nodes, internodes and scale leaves that stores food.', difficulty: 'easy' },
  { id: 'mofp-19', type: 'mcq', question: 'The eyes on a potato tuber, which are the sunken nodes bearing buds, correspond to the:', options: ['Root hairs', 'Nodes of a normal stem', 'Leaves', 'Adventitious roots'], correctIndex: 1, explanation: 'A potato tuber is a swollen stem tip; its "eyes" are nodes bearing axillary buds, showing its stem nature despite growing underground.', difficulty: 'medium' },
  { id: 'mofp-20', type: 'mcq', question: 'A flattened disc-like underground stem covered by scaly leaves, as seen in Colocasia, is called a:', options: ['Bulb', 'Corm', 'Rhizome', 'Tuber'], correctIndex: 1, explanation: 'Colocasia possesses a corm — a stem that grows vertically underground, covered by scaly leaves.', difficulty: 'medium' },
  { id: 'mofp-21', type: 'mcq', question: 'In onion, the fleshy edible part is mainly composed of:', options: ['Fleshy scale leaves surrounding a short stem', 'A swollen root', 'A swollen rhizome', 'Cortical tissue of the stem'], correctIndex: 0, explanation: 'A bulb, as in onion, has a small disc-like stem at the base surrounded by concentric fleshy scale leaves.', difficulty: 'medium' },
  { id: 'mofp-22', type: 'mcq', question: 'A sub-aerial stem modification that grows horizontally along the soil surface, rooting at nodes, as in grass, is called a:', options: ['Runner', 'Sucker', 'Offset', 'Stolon'], correctIndex: 0, explanation: 'Runners are prostrate, slender lateral branches that creep along the soil surface, as seen in grasses like Cynodon.', difficulty: 'medium' },
  { id: 'mofp-23', type: 'mcq', question: 'The lateral branch that arises from the base of the main axis, grows horizontally and produces a new plant at its tip, as in Pistia, is termed an:', options: ['Offset', 'Sucker', 'Stolon', 'Runner'], correctIndex: 0, explanation: 'In aquatic plants like Pistia and Eichhornia, this lateral branch is called an offset.', difficulty: 'medium' },
  { id: 'mofp-24', type: 'mcq', question: 'Underground sub-aerial branches that arise from the basal underground portion of the stem and come out obliquely upward, as in Chrysanthemum, are called:', options: ['Stolons', 'Suckers', 'Offsets', 'Runners'], correctIndex: 1, explanation: 'A sucker is an underground sub-aerial stem branch that grows horizontally below the soil and emerges obliquely, forming a leafy shoot.', difficulty: 'hard' },
  { id: 'mofp-25', type: 'mcq', question: 'Axillary buds that get modified into slender, spirally coiled structures for climbing, as in Cucurbita and grapevine, are called:', options: ['Thorns', 'Tendrils', 'Phylloclades', 'Bulbils'], correctIndex: 1, explanation: 'In weak-stemmed climbers, the axillary bud may modify into a thin, wiry, spirally coiled tendril to help the plant climb.', difficulty: 'easy' },
  { id: 'mofp-26', type: 'mcq', question: 'In Citrus and Bougainvillea, axillary buds are modified into hard, pointed structures called:', options: ['Tendrils', 'Thorns', 'Phylloclades', 'Cladodes'], correctIndex: 1, explanation: 'These woody, sharp, pointed structures develop from axillary buds and protect the plant against browsing animals.', difficulty: 'easy' },
  { id: 'mofp-27', type: 'mcq', question: 'Flattened, green, photosynthetic stems with reduced leaves, adapted for water conservation in xerophytes such as Opuntia, are called:', options: ['Phylloclades', 'Bulbils', 'Cladodes', 'Rhizomes'], correctIndex: 0, explanation: 'In Opuntia, the stem is modified into a flattened, fleshy, green phylloclade that takes over photosynthesis, while the leaves are reduced to spines.', difficulty: 'medium' },
  { id: 'mofp-28', type: 'mcq', question: 'Which of the following stem modifications develops into a new plant when detached, as seen in the "bulbils" of Agave?', options: ['A modification of vegetative or floral buds into fleshy structures storing food for vegetative propagation', 'A root tuber', 'A rhizome', 'A stolon'], correctIndex: 0, explanation: 'Bulbils are modified buds (vegetative or floral) that store food and help in vegetative propagation, as in Agave and Dioscorea.', difficulty: 'medium' },
  { id: 'mofp-29', type: 'assertion', question: 'Assertion (A): The potato tuber is regarded as a modified stem and not a root.\nReason (R): The tuber bears nodes and internodes with axillary buds called "eyes" that can sprout into new plants.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The presence of nodes, internodes and axillary buds (eyes) on the potato tuber confirms its stem origin, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'mofp-30', type: 'matching', question: 'Match Column I (stem modification) with Column II (example):\nColumn I: A. Rhizome  B. Corm  C. Bulb  D. Phylloclade\nColumn II: i. Onion  ii. Opuntia  iii. Ginger  iv. Colocasia', options: ['A-iii, B-iv, C-i, D-ii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-ii, D-i', 'A-iii, B-i, C-iv, D-ii'], correctIndex: 0, explanation: 'Rhizome — Ginger; Corm — Colocasia; Bulb — Onion; Phylloclade — Opuntia.', difficulty: 'medium' },

  // ============ LEAF ============
  { id: 'mofp-31', type: 'mcq', question: 'The leaf develops as a lateral outgrowth from which region of the shoot apex?', options: ['Apical meristem', 'Shoot apical bud', 'Node', 'Internode'], correctIndex: 2, explanation: 'Leaves are lateral, generally flattened structures that develop exogenously at the nodes of the stem and bear axillary buds in their axils.', difficulty: 'easy' },
  { id: 'mofp-32', type: 'mcq', question: 'A typical dorsiventral (dicot) leaf consists of three main parts, namely:', options: ['Leaf base, petiole and lamina', 'Sheath, blade and stipule', 'Petiole, midrib and vein', 'Node, internode and lamina'], correctIndex: 0, explanation: 'A typical angiosperm leaf has a leaf base that attaches it to the stem, a petiole, and an expanded green lamina.', difficulty: 'easy' },
  { id: 'mofp-33', type: 'mcq', question: 'The leaf base in leguminous plants like pea often becomes swollen; this swollen part is called the:', options: ['Stipule', 'Sheath', 'Pulvinus', 'Ligule'], correctIndex: 2, explanation: 'In some leguminous plants, the leaf base is swollen and is known as the pulvinus.', difficulty: 'medium' },
  { id: 'mofp-34', type: 'mcq', question: 'In monocots such as grasses, the leaf base expands into a structure that partially or wholly encloses the stem, called the:', options: ['Petiole', 'Sheath', 'Lamina', 'Rachis'], correctIndex: 1, explanation: 'In monocotyledons, the leaf base expands into a sheath that partly or completely covers the stem.', difficulty: 'medium' },
  { id: 'mofp-35', type: 'mcq', question: 'A network-like arrangement of veins and veinlets in the lamina, typically found in dicot leaves, is called:', options: ['Parallel venation', 'Reticulate venation', 'Unicostate venation', 'Multicostate venation'], correctIndex: 1, explanation: 'When veinlets form a network in dicot leaves, the venation is called reticulate.', difficulty: 'easy' },
  { id: 'mofp-36', type: 'mcq', question: 'The venation pattern in which the veins run parallel to each other within a lamina, as typically seen in monocot leaves, is called:', options: ['Reticulate venation', 'Unicostate reticulate venation', 'Parallel venation', 'Multicostate reticulate venation'], correctIndex: 2, explanation: 'When veins run parallel to each other within the lamina, as in most monocots, the venation is termed parallel.', difficulty: 'easy' },
  { id: 'mofp-37', type: 'mcq', question: 'A simple leaf differs from a compound leaf in that:', options: ['The lamina of a simple leaf is entire or incised but not divided into leaflets, while a compound leaf has its lamina divided into leaflets', 'A simple leaf has parallel venation only', 'A compound leaf never has an axillary bud', 'A simple leaf always has stipules'], correctIndex: 0, explanation: 'In a simple leaf, the lamina is entire or incised but incisions do not reach the midrib; in a compound leaf, the incisions reach the midrib, dividing it into leaflets.', difficulty: 'medium' },
  { id: 'mofp-38', type: 'mcq', question: 'A pinnately compound leaf, as in neem, has leaflets arranged:', options: ['On a common axis, the rachis, representing the midrib of the leaf', 'Radiating from a common point at the tip of the petiole', 'In a spiral around the stem', 'Only at the base of the petiole'], correctIndex: 0, explanation: 'In pinnately compound leaves, a number of leaflets are present on a common axis called the rachis, which represents the midrib.', difficulty: 'medium' },
  { id: 'mofp-39', type: 'mcq', question: 'A palmately compound leaf, as seen in silk cotton, has leaflets that:', options: ['Attach at a common point, at the tip of the petiole', 'Are arranged along a rachis', 'Are arranged in two rows along the stem', 'Fuse together to form a single lamina'], correctIndex: 0, explanation: 'In palmately compound leaves, all the leaflets are attached at a common point, i.e., at the tip of the petiole.', difficulty: 'medium' },
  { id: 'mofp-40', type: 'mcq', question: 'The mode of arrangement of leaves on the stem or its branches is known as:', options: ['Vernation', 'Phyllotaxy', 'Aestivation', 'Placentation'], correctIndex: 1, explanation: 'Phyllotaxy is the pattern of arrangement of leaves on the stem or branch; common types are alternate, opposite and whorled.', difficulty: 'easy' },
  { id: 'mofp-41', type: 'mcq', question: 'When a single leaf arises at each node in an alternating manner on the stem, as in Hibiscus, the phyllotaxy is called:', options: ['Opposite', 'Whorled', 'Alternate', 'Decussate'], correctIndex: 2, explanation: 'In alternate phyllotaxy, a single leaf arises at each node alternately, as seen in China rose, mustard and sunflower.', difficulty: 'easy' },
  { id: 'mofp-42', type: 'mcq', question: 'When a pair of leaves arises at each node and lies opposite to each other, as in Calotropis and guava, the phyllotaxy is called:', options: ['Alternate', 'Opposite', 'Whorled', 'Spiral'], correctIndex: 1, explanation: 'In opposite phyllotaxy, a pair of leaves arises at each node and is positioned opposite to each other.', difficulty: 'easy' },
  { id: 'mofp-43', type: 'mcq', question: 'When more than two leaves arise at a node and form a whorl, as in Alstonia, the phyllotaxy is called:', options: ['Alternate', 'Opposite', 'Whorled', 'Decussate'], correctIndex: 2, explanation: 'In whorled phyllotaxy, more than two leaves arise at a node and form a whorl around it, as seen in Alstonia.', difficulty: 'easy' },
  { id: 'mofp-44', type: 'mcq', question: 'In pea plants, the terminal leaflets of the compound leaf are modified into slender, coiling structures called:', options: ['Thorns', 'Tendrils', 'Spines', 'Phyllodes'], correctIndex: 1, explanation: 'In pea, the tip of the leaf is modified into a tendril that helps the plant climb.', difficulty: 'easy' },
  { id: 'mofp-45', type: 'mcq', question: 'In Australian Acacia, photosynthesis is carried out mainly by the flattened, green, leaf-like structure called the:', options: ['Cladode', 'Phyllode', 'Phylloclade', 'Sheath'], correctIndex: 1, explanation: 'In Australian Acacia, the leaves are reduced and the petiole becomes flattened, forming a green photosynthetic phyllode.', difficulty: 'medium' },
  { id: 'mofp-46', type: 'mcq', question: 'In insectivorous plants like the pitcher plant, leaves are modified into a pitcher-like structure primarily to:', options: ['Store excess water', 'Trap and digest insects, compensating for nitrogen deficiency', 'Aid in vegetative propagation', 'Protect the plant from herbivores'], correctIndex: 1, explanation: 'In insectivorous plants growing in nitrogen-deficient soils, leaves are modified to trap and digest insects and supplement nutrition.', difficulty: 'medium' },
  { id: 'mofp-47', type: 'assertion', question: 'Assertion (A): Leaves of Australian Acacia carry out photosynthesis despite being reduced.\nReason (R): In these plants, the petiole becomes flattened and functions as a phyllode which performs the function of photosynthesis.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The flattened petiole (phyllode) takes over photosynthesis when the leaf lamina is reduced, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'mofp-48', type: 'count', question: 'Consider the following statements about leaf modifications:\n1. In pea, the leaf tip is modified into a tendril.\n2. In Australian Acacia, the leaf lamina performs photosynthesis while the petiole is reduced.\n3. In Opuntia, the leaves are reduced to spines and the stem performs photosynthesis.\n4. Pitcher plant leaves are modified for trapping insects to supplement nitrogen requirement.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is incorrect — in Acacia, the petiole (not the lamina) becomes the flattened photosynthetic phyllode.', difficulty: 'hard' },
  { id: 'mofp-49', type: 'matching', question: 'Match Column I (leaf modification) with Column II (example):\nColumn I: A. Tendril  B. Phyllode  C. Pitcher  D. Spine\nColumn II: i. Nepenthes  ii. Opuntia  iii. Pea  iv. Australian Acacia', options: ['A-iii, B-iv, C-i, D-ii', 'A-iv, B-iii, C-ii, D-i', 'A-iii, B-i, C-iv, D-ii', 'A-i, B-ii, C-iii, D-iv'], correctIndex: 0, explanation: 'Tendril — Pea; Phyllode — Australian Acacia; Pitcher — Nepenthes; Spine — Opuntia.', difficulty: 'medium' },
  { id: 'mofp-50', type: 'mcq', question: 'When the margin of one lamina touches the margin of the adjacent one, arrangement of leaves in a bud is called:', options: ['Valvate vernation', 'Twisted vernation', 'Imbricate vernation', 'Convolute vernation'], correctIndex: 0, explanation: 'Vernation describes the arrangement of leaves in a bud; in valvate vernation, the margins of adjacent leaves just touch without overlapping.', difficulty: 'hard' },

  // ============ INFLORESCENCE ============
  { id: 'mofp-51', type: 'mcq', question: 'The arrangement of flowers on the floral axis is termed the:', options: ['Inflorescence', 'Aestivation', 'Vernation', 'Placentation'], correctIndex: 0, explanation: 'Flowers are arranged on the floral axis in a definite pattern called inflorescence.', difficulty: 'easy' },
  { id: 'mofp-52', type: 'mcq', question: 'In a racemose inflorescence, the main axis:', options: ['Continues to grow and gives off flowers laterally in an acropetal succession', 'Terminates in a flower', 'Stops growing after the first flower opens', 'Gives rise to flowers in basipetal succession'], correctIndex: 0, explanation: 'In racemose inflorescences, the main axis continues to elongate, and flowers are borne laterally in acropetal order (older flowers below, younger ones near the tip).', difficulty: 'medium' },
  { id: 'mofp-53', type: 'mcq', question: 'In a cymose inflorescence, the main axis:', options: ['Terminates in a flower, and hence is limited in growth', 'Grows indefinitely', 'Never bears a terminal flower', 'Bears flowers in acropetal order'], correctIndex: 0, explanation: 'In cymose inflorescences, the main axis terminates in a flower and is therefore limited in growth; flowers are borne in basipetal order.', difficulty: 'medium' },
  { id: 'mofp-54', type: 'mcq', question: 'An inflorescence with an elongated axis and sessile flowers, as in Achyranthes, is called a:', options: ['Raceme', 'Spike', 'Corymb', 'Umbel'], correctIndex: 1, explanation: 'A spike is a type of racemose inflorescence in which the main axis is elongated and the flowers are sessile (without pedicels).', difficulty: 'easy' },
  { id: 'mofp-55', type: 'mcq', question: 'An inflorescence in which pedicellate flowers are borne on an elongated axis, as in mustard and Larkspur, is called a:', options: ['Raceme', 'Spike', 'Catkin', 'Spadix'], correctIndex: 0, explanation: 'A raceme has an elongated main axis bearing flowers with pedicels, in acropetal order.', difficulty: 'easy' },
  { id: 'mofp-56', type: 'mcq', question: 'A spike-like inflorescence in which the axis is fleshy and enclosed by a large, colourful bract called a spathe, as in banana, is termed a:', options: ['Catkin', 'Spadix', 'Corymb', 'Capitulum'], correctIndex: 1, explanation: 'In a spadix inflorescence, the axis is fleshy and generally enclosed by a large bract known as spathe, as in banana and the palm family.', difficulty: 'medium' },
  { id: 'mofp-57', type: 'mcq', question: 'In an umbellate inflorescence, all the pedicels of flowers arise from the tip of the peduncle at:', options: ['Different levels', 'The same point, giving an umbrella-like appearance', 'Alternating nodes', 'Two opposite points'], correctIndex: 1, explanation: 'In an umbel, all flower pedicels arise from a common point at the top of the peduncle, resembling an umbrella, as in onion and coriander.', difficulty: 'medium' },
  { id: 'mofp-58', type: 'mcq', question: 'A corymb is a racemose inflorescence in which flowers are:', options: ['Sessile along the main axis', 'Arranged such that they attain nearly the same level due to differing pedicel lengths', 'Arranged in a spiral', 'Restricted to a single terminal flower'], correctIndex: 1, explanation: 'In a corymb, though borne on an elongated axis, the pedicels of the lower flowers are longer so that all flowers reach roughly the same level, as in Iberis (candytuft).', difficulty: 'medium' },
  { id: 'mofp-59', type: 'mcq', question: 'A capitulum (head) inflorescence, as seen in sunflower, consists of:', options: ['A single large flower', 'A flattened axis bearing many small sessile flowers called florets, surrounded by an involucre of bracts', 'A single elongated axis with alternating flowers', 'A cluster of umbels'], correctIndex: 1, explanation: 'In a head/capitulum, the axis becomes condensed and flattened, bearing many sessile flowers (florets) surrounded by an involucre of bracts.', difficulty: 'medium' },
  { id: 'mofp-60', type: 'mcq', question: 'Uniparous cyme is a type of cymose inflorescence in which the peduncle produces:', options: ['A single lateral branch at a time', 'Two lateral branches at a time', 'More than two lateral branches simultaneously', 'No lateral branches at all'], correctIndex: 0, explanation: 'In a uniparous cyme, the peduncle bears a terminal flower and gives off only a single lateral branch, which again ends in a flower.', difficulty: 'hard' },

  // ============ FLOWER ============
  { id: 'mofp-61', type: 'mcq', question: 'The flower is a modified shoot meant for:', options: ['Vegetative propagation', 'Sexual reproduction', 'Food storage', 'Gas exchange'], correctIndex: 1, explanation: 'A flower is essentially a modified condensed shoot wherein the shoot apical meristem changes to a floral meristem for sexual reproduction.', difficulty: 'easy' },
  { id: 'mofp-62', type: 'mcq', question: 'When a flower can be divided into two equal radial halves in any radial plane passing through the centre, it is said to be:', options: ['Zygomorphic', 'Actinomorphic', 'Asymmetric', 'Irregular'], correctIndex: 1, explanation: 'A flower is actinomorphic (regular/radially symmetrical) when it can be divided into two equal radial halves in any vertical plane through the centre, e.g., mustard and Datura.', difficulty: 'medium' },
  { id: 'mofp-63', type: 'mcq', question: 'A flower that can be divided into two similar halves only in one particular vertical plane is called:', options: ['Actinomorphic', 'Zygomorphic', 'Asymmetric', 'Trimerous'], correctIndex: 1, explanation: 'A zygomorphic (irregular/bilaterally symmetrical) flower can be divided into two equal halves in only one plane, e.g., pea and Cassia.', difficulty: 'medium' },
  { id: 'mofp-64', type: 'mcq', question: 'A flower that cannot be divided into two equal halves by any plane through the centre is called:', options: ['Actinomorphic', 'Zygomorphic', 'Asymmetric (irregular)', 'Polysymmetric'], correctIndex: 2, explanation: 'When a flower cannot be divided into two equal halves by any vertical plane, it is termed asymmetric, e.g., Canna.', difficulty: 'medium' },
  { id: 'mofp-65', type: 'mcq', question: 'A flower having both androecium and gynoecium is called:', options: ['Unisexual', 'Bisexual', 'Neuter', 'Asexual'], correctIndex: 1, explanation: 'When a flower has both stamens and carpels, it is bisexual; when it has only one of the two, it is unisexual (either male or female).', difficulty: 'easy' },
  { id: 'mofp-66', type: 'mcq', question: 'The condition in which the calyx, corolla, androecium and gynoecium are attached to the thalamus in an acropetal order, with the ovary in the highest position, is called:', options: ['Hypogyny', 'Perigyny', 'Epigyny', 'Isogyny'], correctIndex: 0, explanation: 'In hypogynous flowers, the gynoecium occupies the highest position while the other parts are borne below it; the ovary is described as superior, e.g., mustard, china rose.', difficulty: 'medium' },
  { id: 'mofp-67', type: 'mcq', question: 'When the margin of the thalamus grows upward, enclosing the ovary partially, with the other floral parts arising at nearly the same level as the ovary, the condition is called:', options: ['Hypogyny (superior ovary)', 'Perigyny (half-inferior ovary)', 'Epigyny (inferior ovary)', 'None of the above'], correctIndex: 1, explanation: 'In perigynous flowers, the gynoecium is in the centre and the other parts are arranged around it at the same level, giving a half-inferior ovary, e.g., plum, rose, peach.', difficulty: 'medium' },
  { id: 'mofp-68', type: 'mcq', question: 'When the thalamus grows upward and completely encloses the ovary, fusing with it, such that the other floral parts arise above the ovary, the ovary is termed:', options: ['Superior', 'Half-inferior', 'Inferior', 'Free'], correctIndex: 2, explanation: 'In epigynous flowers (e.g., guava, sunflower florets, cucumber), the ovary is inferior as the thalamus grows upward and completely encloses it, with other whorls arising above.', difficulty: 'medium' },
  { id: 'mofp-69', type: 'mcq', question: 'The mode of arrangement of sepals or petals in a floral bud with respect to the other members of the same whorl is called:', options: ['Placentation', 'Aestivation', 'Phyllotaxy', 'Vernation'], correctIndex: 1, explanation: 'Aestivation refers to the pattern in which sepals or petals are arranged in a floral bud relative to other members of the same whorl.', difficulty: 'easy' },
  { id: 'mofp-70', type: 'mcq', question: 'When sepals or petals in a whorl just touch one another at the margin without overlapping, as in Calotropis, the aestivation is called:', options: ['Twisted', 'Valvate', 'Imbricate', 'Vexillary'], correctIndex: 1, explanation: 'In valvate aestivation, sepals/petals of the same whorl just touch each other at their margins without overlapping.', difficulty: 'medium' },
  { id: 'mofp-71', type: 'mcq', question: 'When one margin of a petal overlaps the margin of the next petal, and this continues around the whorl, the aestivation is called:', options: ['Valvate', 'Twisted', 'Imbricate', 'Vexillary'], correctIndex: 1, explanation: 'In twisted aestivation, one margin of every appendage overlaps the margin of the next one consistently, as in China rose and lady\'s finger.', difficulty: 'medium' },
  { id: 'mofp-72', type: 'mcq', question: 'When the margins of sepals or petals overlap one another but not in any particular direction, the aestivation is called:', options: ['Valvate', 'Twisted', 'Imbricate', 'Vexillary'], correctIndex: 2, explanation: 'In imbricate aestivation, the margins of floral appendages overlap one another but not in any specific direction, e.g., Cassia and gulmohar.', difficulty: 'medium' },
  { id: 'mofp-73', type: 'mcq', question: 'Vexillary (papilionaceous) aestivation, characteristic of the pea flower, is a special type of aestivation in which:', options: ['All five petals are equal in size', 'The largest posterior petal (standard) overlaps the two lateral petals (wings), which in turn overlap the two smallest anterior petals (keel)', 'All petals are free and non-overlapping', 'Only sepals overlap, not petals'], correctIndex: 1, explanation: 'In vexillary aestivation, there are five petals — the largest (standard/vexillum) overlaps the two lateral wing petals, which in turn overlap the two anterior keel petals.', difficulty: 'hard' },
  { id: 'mofp-74', type: 'mcq', question: 'The calyx forms the ______ whorl of a flower and is usually:', options: ['Outermost; green', 'Innermost; colourful', 'Second; green', 'Third; colourful'], correctIndex: 0, explanation: 'The calyx is the outermost whorl of the flower, made up of sepals, and is usually green and protects the flower in the bud stage.', difficulty: 'easy' },
  { id: 'mofp-75', type: 'mcq', question: 'The corolla is composed of units called petals, which are usually:', options: ['Green and protective', 'Brightly coloured to attract pollinators', 'Reduced to scales', 'Fused with the sepals'], correctIndex: 1, explanation: 'The corolla is made of petals which are usually brightly coloured to attract insects for pollination.', difficulty: 'easy' },
  { id: 'mofp-76', type: 'mcq', question: 'A corolla in which the petals are united is called ______, while one with free petals is called ______.', options: ['Polypetalous; gamopetalous', 'Gamopetalous; polypetalous', 'Gamosepalous; polysepalous', 'Actinomorphic; zygomorphic'], correctIndex: 1, explanation: 'Petals may be free (polypetalous) or united (gamopetalous), showing various shapes like tubular, campanulate, funnel-shaped or rotate.', difficulty: 'easy' },
  { id: 'mofp-77', type: 'mcq', question: 'The androecium is composed of stamens, each of which typically has:', options: ['A filament and an anther', 'A filament and a stigma', 'A style and an anther', 'A petal and a filament'], correctIndex: 0, explanation: 'Each stamen (male reproductive part) generally has a stalk called the filament and an anther, usually bilobed, with each lobe having two chambers (pollen sacs).', difficulty: 'easy' },
  { id: 'mofp-78', type: 'mcq', question: 'When stamens are attached to the petals, the condition is called:', options: ['Epipetalous', 'Epiphyllous', 'Adelphous', 'Syngenesious'], correctIndex: 0, explanation: 'Epipetalous stamens are those attached to the petals, as in brinjal.', difficulty: 'medium' },
  { id: 'mofp-79', type: 'mcq', question: 'When stamens in a flower are united into more than two bundles, the condition is called:', options: ['Monoadelphous', 'Diadelphous', 'Polyadelphous', 'Syngenesious'], correctIndex: 2, explanation: 'Polyadelphous stamens are united into more than two bundles, e.g., citrus.', difficulty: 'medium' },
  { id: 'mofp-80', type: 'mcq', question: 'In pea flowers, the ten stamens are united into two bundles (nine + one), a condition called:', options: ['Monoadelphous', 'Diadelphous', 'Polyadelphous', 'Syngenesious'], correctIndex: 1, explanation: 'Diadelphous stamens are united into two bundles, as seen in pea (9 fused + 1 free).', difficulty: 'medium' },
  { id: 'mofp-81', type: 'mcq', question: 'The gynoecium is composed of one or more carpels, each of which typically consists of:', options: ['Stigma, style and ovary', 'Filament and anther', 'Sepal and petal', 'Pedicel and thalamus'], correctIndex: 0, explanation: 'A carpel is made up of an ovary (basal, bulged part containing ovules), a style (elongated tube), and a stigma (terminal part, often sticky, that receives pollen).', difficulty: 'easy' },
  { id: 'mofp-82', type: 'mcq', question: 'When more than one carpel is present and they are fused together, the gynoecium is called:', options: ['Apocarpous', 'Syncarpous', 'Monocarpellary', 'Unilocular'], correctIndex: 1, explanation: 'A syncarpous gynoecium has fused carpels, as in mustard and tomato; when carpels are free, it is called apocarpous, as in lotus and rose.', difficulty: 'medium' },
  { id: 'mofp-83', type: 'mcq', question: 'The arrangement of ovules within the ovary is called:', options: ['Aestivation', 'Placentation', 'Vernation', 'Phyllotaxy'], correctIndex: 1, explanation: 'Placentation refers to the arrangement pattern of ovules within the ovary.', difficulty: 'easy' },
  { id: 'mofp-84', type: 'mcq', question: 'When the placenta forms a ridge along the ventral suture of the ovary and ovules develop on it, as in pea, the placentation is called:', options: ['Marginal', 'Axile', 'Parietal', 'Free central'], correctIndex: 0, explanation: 'In marginal placentation, the placenta develops along the ventral suture of a unilocular ovary, bearing ovules in two rows, as in pea.', difficulty: 'medium' },
  { id: 'mofp-85', type: 'mcq', question: 'In China rose and tomato, the placenta is axial and ovules are attached in a multilocular ovary; this placentation is called:', options: ['Marginal', 'Axile', 'Parietal', 'Basal'], correctIndex: 1, explanation: 'In axile placentation, the placenta is central, and the ovules are attached to it, forming a multilocular ovary, e.g., China rose, tomato and lemon.', difficulty: 'medium' },
  { id: 'mofp-86', type: 'mcq', question: 'In mustard and Argemone, ovules develop on the inner wall of the ovary or on peripheral parts, and the ovary is one-chambered but becomes two-chambered due to a false septum; this placentation is called:', options: ['Marginal', 'Axile', 'Parietal', 'Free central'], correctIndex: 2, explanation: 'In parietal placentation, ovules develop on the inner wall of the ovary or on peripheral part; the ovary is one-chambered but becomes two-chambered due to a false septum.', difficulty: 'hard' },
  { id: 'mofp-87', type: 'mcq', question: 'In Dianthus and Primrose, the ovules are borne on the central axis without any septa, and the ovary is unilocular; this placentation is called:', options: ['Marginal', 'Axile', 'Free central', 'Basal'], correctIndex: 2, explanation: 'In free central placentation, ovules are borne on the central axis, and septa are absent, so the ovary is unilocular.', difficulty: 'hard' },
  { id: 'mofp-88', type: 'mcq', question: 'In sunflower and marigold, the ovule develops at the base of the ovary; this placentation is called:', options: ['Marginal', 'Basal', 'Parietal', 'Axile'], correctIndex: 1, explanation: 'In basal placentation, the placenta develops at the base of the ovary, and a single ovule is attached to it, as in sunflower.', difficulty: 'medium' },
  { id: 'mofp-89', type: 'assertion', question: 'Assertion (A): In brinjal, the flower is described as hypogynous with a superior ovary.\nReason (R): In hypogynous flowers, the gynoecium is at the highest position and other floral whorls are inserted below it on the thalamus.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Brinjal flowers are hypogynous with a superior ovary because the gynoecium sits at the highest point on the thalamus, exactly as R describes.', difficulty: 'medium' },
  { id: 'mofp-90', type: 'assertion', question: 'Assertion (A): In guava flowers, the ovary is described as inferior.\nReason (R): In epigynous flowers, the thalamus grows upward, encloses the ovary completely, and fuses with it, so other floral parts arise above the ovary.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Guava is a classic example of an epigynous flower with an inferior ovary, matching the mechanism described in R.', difficulty: 'medium' },
  { id: 'mofp-91', type: 'matching', question: 'Match Column I (placentation type) with Column II (example):\nColumn I: A. Marginal  B. Axile  C. Parietal  D. Free central\nColumn II: i. Mustard  ii. Dianthus  iii. Pea  iv. Tomato', options: ['A-iii, B-iv, C-i, D-ii', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-i, C-iv, D-ii', 'A-iv, B-iii, C-ii, D-i'], correctIndex: 0, explanation: 'Marginal — Pea; Axile — Tomato; Parietal — Mustard; Free central — Dianthus.', difficulty: 'hard' },
  { id: 'mofp-92', type: 'matching', question: 'Match Column I (aestivation type) with Column II (example):\nColumn I: A. Valvate  B. Twisted  C. Imbricate  D. Vexillary\nColumn II: i. Pea  ii. Calotropis  iii. Gulmohar  iv. China rose', options: ['A-ii, B-iv, C-iii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-i, C-ii, D-iii', 'A-ii, B-iii, C-iv, D-i'], correctIndex: 0, explanation: 'Valvate — Calotropis; Twisted — China rose; Imbricate — Gulmohar; Vexillary — Pea.', difficulty: 'hard' },
  { id: 'mofp-93', type: 'count', question: 'Consider the following statements about the flower:\n1. Calyx is always the innermost whorl of a flower.\n2. Androecium represents the male reproductive whorl.\n3. Gynoecium is composed of one or more carpels.\n4. A bisexual flower contains both androecium and gynoecium.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 2, 3 and 4 are correct. Statement 1 is wrong — the calyx is the outermost whorl, not the innermost.', difficulty: 'medium' },
  { id: 'mofp-94', type: 'count', question: 'Consider the following statements about placentation:\n1. In marginal placentation, the ovary is typically unilocular with ovules in two rows.\n2. In axile placentation, the ovary is multilocular.\n3. Free central placentation is found in Dianthus, where the ovary is unilocular without septa.\n4. Parietal placentation always results in a permanently unilocular ovary.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is incorrect — in parietal placentation the ovary is one-chambered but often becomes two-chambered due to a false septum (e.g., mustard).', difficulty: 'hard' },
  { id: 'mofp-95', type: 'mcq', question: 'The floral formula symbol "⊕" represents:', options: ['Zygomorphic flower', 'Actinomorphic flower', 'Bisexual flower', 'Epigynous flower'], correctIndex: 1, explanation: 'In floral formulas, ⊕ denotes actinomorphic (radially symmetrical) flowers, while a special bracket-like symbol denotes zygomorphic flowers.', difficulty: 'medium' },
  { id: 'mofp-96', type: 'mcq', question: 'In a floral formula, the letters K, C, A and G respectively represent:', options: ['Calyx, corolla, androecium, gynoecium', 'Corolla, calyx, gynoecium, androecium', 'Calyx, androecium, corolla, gynoecium', 'Gynoecium, androecium, corolla, calyx'], correctIndex: 0, explanation: 'The floral formula uses K for calyx, C for corolla, A for androecium and G for gynoecium, along with numbers indicating the members in each whorl.', difficulty: 'easy' },
  { id: 'mofp-97', type: 'mcq', question: 'A line drawn above the numeral of the gynoecium in a floral formula (e.g., G) indicates that the ovary is:', options: ['Superior', 'Inferior', 'Half-inferior', 'Absent'], correctIndex: 1, explanation: 'A line above the gynoecium symbol indicates an inferior ovary, while a line below indicates a superior ovary.', difficulty: 'hard' },
  { id: 'mofp-98', type: 'mcq', question: 'The diagrammatic, cross-sectional representation of the number, arrangement and relative position of floral parts is called a:', options: ['Floral formula', 'Floral diagram', 'Inflorescence chart', 'Placentation map'], correctIndex: 1, explanation: 'A floral diagram gives information about the number of parts, their arrangement and their relation to one another in the flower.', difficulty: 'easy' },
  { id: 'mofp-99', type: 'mcq', question: 'When petals in the corolla are shaped so that the tube is small and the limb is spread flat, as in Datura, the shape is described as:', options: ['Tubular', 'Campanulate', 'Funnel-shaped', 'Rotate'], correctIndex: 2, explanation: 'A funnel-shaped (infundibuliform) corolla, as in Datura, has a tube that gradually widens like a funnel.', difficulty: 'hard' },
  { id: 'mofp-100', type: 'mcq', question: 'A pedicellate, complete flower with a bract at its base, showing calyx, corolla, androecium and gynoecium, would be classified as:', options: ['Ebracteate', 'Bracteate', 'Sessile', 'Incomplete'], correctIndex: 1, explanation: 'A flower with a bract at its base is called bracteate; if the bract is absent, the flower is ebracteate.', difficulty: 'easy' },

  // ============ FRUIT ============
  { id: 'mofp-101', type: 'mcq', question: 'The fruit is defined as a matured and ripened:', options: ['Ovule', 'Ovary', 'Stamen', 'Sepal'], correctIndex: 1, explanation: 'The fruit is a characteristic feature of flowering plants, developing after fertilisation from the mature, ripened ovary.', difficulty: 'easy' },
  { id: 'mofp-102', type: 'mcq', question: 'A fruit that develops from the ovary without fertilisation, as sometimes seen in banana, is called:', options: ['True fruit', 'False fruit', 'Parthenocarpic fruit', 'Aggregate fruit'], correctIndex: 2, explanation: 'When fruits develop from the ovary without fertilisation, they are called parthenocarpic fruits and are generally seedless.', difficulty: 'medium' },
  { id: 'mofp-103', type: 'mcq', question: 'The fruit wall, developing from the wall of the ovary after fertilisation, is called the:', options: ['Testa', 'Pericarp', 'Tegmen', 'Hilum'], correctIndex: 1, explanation: 'The wall of the ovary develops into the fruit wall, called the pericarp, which may be dry or fleshy.', difficulty: 'easy' },
  { id: 'mofp-104', type: 'mcq', question: 'When the pericarp of a fleshy fruit is differentiated into an outer thin epicarp, a fleshy middle mesocarp, and an inner hard endocarp, as in mango, the fruit is called a:', options: ['Berry', 'Drupe', 'Pome', 'Legume'], correctIndex: 1, explanation: 'A drupe is a fleshy fruit with a clearly differentiated pericarp: thin epicarp, fleshy mesocarp, and hard, stony endocarp enclosing a single seed, as in mango and coconut.', difficulty: 'medium' },
  { id: 'mofp-105', type: 'mcq', question: 'Fruits that develop from a flower with more than one carpel in the same flower, where all the carpels combine to form a single fruit, are called:', options: ['Simple fruits', 'Aggregate fruits', 'Composite fruits', 'False fruits'], correctIndex: 1, explanation: 'Aggregate fruits develop from a single flower with multiple free carpels, as in rose and strawberry, where each carpel forms a fruitlet clustered together.', difficulty: 'medium' },
  { id: 'mofp-106', type: 'mcq', question: 'Fruits that develop from an entire inflorescence, such as an entire head or spike, are called:', options: ['Simple fruits', 'Aggregate fruits', 'Composite (multiple) fruits', 'True fruits'], correctIndex: 2, explanation: 'Composite or multiple fruits are formed from an entire inflorescence, e.g., pineapple and mulberry.', difficulty: 'medium' },

  // ============ SEED ============
  { id: 'mofp-107', type: 'mcq', question: 'The seed essentially consists of a seed coat and:', options: ['Only the endosperm', 'An embryo consisting of a radicle, an embryonal axis and one or two cotyledons', 'Only cotyledons', 'A pericarp'], correctIndex: 1, explanation: 'A seed has a seed coat and an embryo, which is made up of a radicle, an embryonal axis and one (monocot) or two (dicot) cotyledons.', difficulty: 'easy' },
  { id: 'mofp-108', type: 'mcq', question: 'In a dicotyledonous seed, the outer and inner seed coats are respectively called:', options: ['Testa and tegmen', 'Tegmen and testa', 'Pericarp and testa', 'Aleurone and testa'], correctIndex: 0, explanation: 'The dicot seed coat has two layers: the outer testa and the inner tegmen.', difficulty: 'medium' },
  { id: 'mofp-109', type: 'mcq', question: 'A small pore present on the seed coat, above the micropyle, that facilitates the entry of oxygen and water into the seed during germination is called the:', options: ['Hilum', 'Raphe', 'Micropyle', 'Micropyle serves this function directly'], correctIndex: 3, explanation: 'The micropyle itself is the small pore on the seed coat that allows entry of oxygen and water for seed germination.', difficulty: 'medium' },
  { id: 'mofp-110', type: 'mcq', question: 'The scar on the seed coat, marking the point where the seed was attached to the fruit wall (funicle), is called the:', options: ['Hilum', 'Micropyle', 'Chalaza', 'Raphe'], correctIndex: 0, explanation: 'The hilum is the scar on the seed coat through which the developing seed was attached to the fruit wall.', difficulty: 'medium' },
  { id: 'mofp-111', type: 'mcq', question: 'Seeds in which the endosperm is used up completely during embryo development and food is instead stored in the cotyledons, as in pea and gram, are called:', options: ['Endospermic seeds', 'Non-endospermic seeds', 'Albuminous seeds', 'Perispermic seeds'], correctIndex: 1, explanation: 'Non-endospermic (exalbuminous) seeds have their endosperm completely consumed during embryo development, with food stored in the cotyledons instead, e.g., pea, gram, groundnut.', difficulty: 'medium' },
  { id: 'mofp-112', type: 'mcq', question: 'Seeds in which the endosperm formed as a result of double fertilisation is not fully used up and remains a food-storing tissue, as in wheat and maize, are called:', options: ['Endospermic seeds', 'Non-endospermic seeds', 'Exalbuminous seeds', 'None of the above'], correctIndex: 0, explanation: 'Endospermic (albuminous) seeds retain part or all of the endosperm as food-storage tissue, as in castor, wheat and maize.', difficulty: 'medium' },
  { id: 'mofp-113', type: 'mcq', question: 'In a maize (monocot) seed, the sheath enclosing the young leaves and shoot apex is called the:', options: ['Coleorhiza', 'Coleoptile', 'Scutellum', 'Endosperm'], correctIndex: 1, explanation: 'In maize, the plumule and radicle are enclosed in sheaths called the coleoptile (plumule sheath) and coleorhiza (radicle sheath), respectively.', difficulty: 'hard' },
  { id: 'mofp-114', type: 'mcq', question: 'In a maize grain, the single, large and shield-shaped cotyledon is called the:', options: ['Aleurone layer', 'Scutellum', 'Testa', 'Tegmen'], correctIndex: 1, explanation: 'In monocot seeds like maize, the single cotyledon is called the scutellum.', difficulty: 'medium' },

  // ============ FAMILIES / SEMI-TECHNICAL DESCRIPTION ============
  { id: 'mofp-115', type: 'mcq', question: 'The family Fabaceae is characterised by which type of aestivation in the corolla?', options: ['Valvate', 'Twisted', 'Imbricate', 'Vexillary'], correctIndex: 3, explanation: 'The Fabaceae (pea family) shows vexillary (papilionaceous) aestivation, typical of the standard, wing and keel petal arrangement.', difficulty: 'medium' },
  { id: 'mofp-116', type: 'mcq', question: 'In Fabaceae, the androecium usually shows which condition of stamens?', options: ['Monoadelphous (all ten fused)', 'Diadelphous (nine fused + one free)', 'Polyadelphous', 'Free stamens, no fusion'], correctIndex: 1, explanation: 'Fabaceae typically has ten stamens, diadelphous — nine fused into a tube and one free.', difficulty: 'medium' },
  { id: 'mofp-117', type: 'mcq', question: 'The fruit type most characteristic of the family Fabaceae is the:', options: ['Berry', 'Legume (pod)', 'Capsule', 'Drupe'], correctIndex: 1, explanation: 'Fabaceae typically produces a legume (pod) fruit that dehisces along both sutures, as in pea and bean.', difficulty: 'easy' },
  { id: 'mofp-118', type: 'mcq', question: 'The floral formula of a typical Fabaceae flower shows the gynoecium as:', options: ['Bicarpellary, syncarpous, superior', 'Monocarpellary, unilocular, superior, with marginal placentation', 'Multicarpellary, syncarpous, inferior', 'Tricarpellary, apocarpous, superior'], correctIndex: 1, explanation: 'In Fabaceae, the gynoecium is monocarpellary, unilocular, with marginal placentation and numerous ovules, and the ovary is superior.', difficulty: 'hard' },
  { id: 'mofp-119', type: 'mcq', question: 'The family Solanaceae is commonly called the potato family and typically shows which aestivation pattern in the corolla?', options: ['Valvate', 'Twisted', 'Imbricate', 'Vexillary'], correctIndex: 1, explanation: 'Solanaceae flowers usually show twisted aestivation in the corolla.', difficulty: 'medium' },
  { id: 'mofp-120', type: 'mcq', question: 'In Solanaceae, the flowers are typically:', options: ['Zygomorphic and bisexual', 'Actinomorphic and bisexual', 'Zygomorphic and unisexual', 'Asymmetric and unisexual'], correctIndex: 1, explanation: 'Flowers of Solanaceae are actinomorphic, bisexual, complete, and pentamerous, e.g., in brinjal, tomato, potato.', difficulty: 'medium' },
  { id: 'mofp-121', type: 'mcq', question: 'The gynoecium in a typical Solanaceae flower shows which type of placentation?', options: ['Marginal', 'Axile', 'Parietal', 'Basal'], correctIndex: 1, explanation: 'The Solanaceae gynoecium is bicarpellary, syncarpous, with axile placentation, and the ovary is superior and obliquely placed.', difficulty: 'hard' },
  { id: 'mofp-122', type: 'mcq', question: 'Which of the following economically important plants does NOT belong to the family Solanaceae?', options: ['Potato', 'Tomato', 'Chilli', 'Wheat'], correctIndex: 3, explanation: 'Wheat belongs to the family Poaceae; potato, tomato and chilli all belong to Solanaceae.', difficulty: 'easy' },
  { id: 'mofp-123', type: 'mcq', question: 'The family Liliaceae belongs to which class of angiosperms?', options: ['Dicotyledonae', 'Monocotyledonae', 'Gymnosperms', 'Pteridophytes'], correctIndex: 1, explanation: 'Liliaceae is a monocot family, commonly called the lily family.', difficulty: 'easy' },
  { id: 'mofp-124', type: 'mcq', question: 'In Liliaceae, the perianth (tepals) is typically arranged in how many whorls, each with how many members?', options: ['One whorl of three', 'Two whorls of three each (six tepals)', 'Two whorls of five each', 'One whorl of five'], correctIndex: 1, explanation: 'In Liliaceae, the perianth consists of two whorls of three tepals each, usually similar in colour and appearance (petaloid).', difficulty: 'medium' },
  { id: 'mofp-125', type: 'mcq', question: 'The androecium in a typical Liliaceae flower usually consists of:', options: ['Three stamens in a single whorl', 'Six stamens in two whorls of three each', 'Ten stamens, diadelphous', 'Numerous stamens, polyandrous'], correctIndex: 1, explanation: 'Liliaceae typically shows six stamens arranged in two whorls of three each, epiphyllous (attached to the tepals).', difficulty: 'medium' },
  { id: 'mofp-126', type: 'assertion', question: 'Assertion (A): The fruit of Fabaceae members like pea is called a legume.\nReason (R): A legume develops from a monocarpellary, unilocular ovary and typically dehisces along both the dorsal and ventral sutures.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The legume/pod fruit of Fabaceae develops exactly as described in R, which correctly explains the assertion.', difficulty: 'medium' },
  { id: 'mofp-127', type: 'count', question: 'Consider the following features of family Liliaceae:\n1. Perianth in two whorls of three tepals each.\n2. Androecium of six stamens in two whorls.\n3. Gynoecium tricarpellary, syncarpous, with axile placentation.\n4. Fruit is typically a legume.\nHow many of the above statements are correct for Liliaceae?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 correctly describe Liliaceae. Statement 4 is wrong — the legume fruit is characteristic of Fabaceae, while Liliaceae typically bears a capsule or berry.', difficulty: 'hard' },
  { id: 'mofp-128', type: 'matching', question: 'Match Column I (family) with Column II (characteristic aestivation/placentation):\nColumn I: A. Fabaceae  B. Solanaceae  C. Liliaceae\nColumn II: i. Twisted aestivation, axile placentation  ii. Vexillary aestivation, marginal placentation  iii. Valvate/twisted perianth, axile placentation', options: ['A-ii, B-i, C-iii', 'A-i, B-ii, C-iii', 'A-iii, B-i, C-ii', 'A-ii, B-iii, C-i'], correctIndex: 0, explanation: 'Fabaceae — vexillary aestivation with marginal placentation; Solanaceae — twisted aestivation with axile placentation; Liliaceae — perianth with axile placentation in the gynoecium.', difficulty: 'hard' },
  { id: 'mofp-129', type: 'mcq', question: 'The semi-technical description of a flowering plant, as prescribed for practical identification, typically follows the sequence:', options: ['Habit and habitat → Root → Stem → Leaf → Inflorescence → Flower (with floral formula and diagram) → Fruit', 'Flower → Fruit → Leaf → Root → Stem', 'Fruit → Seed → Flower → Leaf → Root', 'Inflorescence → Root → Fruit → Flower → Leaf'], correctIndex: 0, explanation: 'A semi-technical description systematically covers habit, root, stem, leaf, inflorescence, flower (with floral formula/diagram) and fruit, in that order.', difficulty: 'medium' },
  { id: 'mofp-130', type: 'mcq', question: 'Which of the following pairs of family and typical fruit type is correctly matched?', options: ['Fabaceae — Legume', 'Solanaceae — Follicle', 'Liliaceae — Legume', 'Fabaceae — Berry only'], correctIndex: 0, explanation: 'Fabaceae is correctly characterised by the legume/pod fruit; Solanaceae typically bears a berry or capsule, and Liliaceae typically bears a capsule or berry, not a legume.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'mofp-131', type: 'count', question: 'Consider the following statements about the androecium:\n1. Epipetalous stamens are attached to the petals.\n2. Monoadelphous stamens are united into a single bundle.\n3. Syngenesious stamens are united by their anthers, with free filaments.\n4. Gynandrous stamens are fused with the gynoecium.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 3, explanation: 'All four statements correctly describe the respective conditions of stamen fusion/attachment used in floral morphology.', difficulty: 'hard' },
  { id: 'mofp-132', type: 'mcq', question: 'The term used for the arrangement of ovules within the ovary, when ovules are borne on the placenta attached to the central axis of a unilocular ovary, is:', options: ['Axile placentation', 'Free central placentation', 'Marginal placentation', 'Parietal placentation'], correctIndex: 1, explanation: 'This describes free central placentation, distinct from axile placentation where the ovary is multilocular with septa.', difficulty: 'medium' },
  { id: 'mofp-133', type: 'mcq', question: 'Which floral whorl is directly responsible for producing pollen grains?', options: ['Calyx', 'Corolla', 'Androecium', 'Gynoecium'], correctIndex: 2, explanation: 'The androecium (stamens) bears anthers containing pollen sacs where pollen grains (microspores) are produced.', difficulty: 'easy' },
  { id: 'mofp-134', type: 'mcq', question: 'A leaf with an incised lamina where the incisions do NOT reach up to the midrib is classified as a:', options: ['Compound leaf', 'Simple leaf', 'Pinnate leaf', 'Trifoliate leaf'], correctIndex: 1, explanation: 'In a simple leaf, the lamina may be entire or incised, but the incisions never reach the midrib.', difficulty: 'medium' },
  { id: 'mofp-135', type: 'mcq', question: 'In a typical racemose inflorescence, the youngest flower is found:', options: ['At the base, farthest from the tip', 'At the tip of the axis', 'In the middle of the axis', 'Racemose inflorescences do not show age-based order'], correctIndex: 1, explanation: 'In racemose inflorescences, flowers open in acropetal succession — older flowers are towards the base and the youngest is near the growing tip.', difficulty: 'medium' },
];